import { expect, test } from "../../fixtures";

test.describe("manage vendors", () => {
  test("the same vendor name is allowed in a different tenant", { tag: "@VEN-04" }, async ({ apiAs }) => {
    const name = "Acme Freight";
    const globex = await apiAs("otherTenant");
    const northwind = await apiAs("member");

    // Given a vendor named "Acme Freight" exists in tenant "Globex Procurement"
    const seed = await globex.post("/api/vendors", {
      data: { name, category: "logistics", contact_email: "ops@acmefreight.example" },
    });
    // 201 on a fresh database; 409 if an earlier run already seeded this vendor.
    expect([201, 409], await seed.text()).toContain(seed.status());

    const seeded = await globex.get("/api/vendors", { params: { q: name } });
    expect(seeded.status(), await seeded.text()).toBe(200);
    const seededPage = await seeded.json();
    expect(
      seededPage.items.some((v: { name: string }) => v.name === name),
      "Globex tenant should list its Acme Freight vendor",
    ).toBe(true);

    // When I create a vendor named "Acme Freight" in category "logistics" with contact "ops@acmefreight.example"
    const res = await northwind.post("/api/vendors", {
      data: { name, category: "logistics", contact_email: "ops@acmefreight.example" },
    });

    // Then the response status is 201
    expect(res.status(), await res.text()).toBe(201);
    const created = await res.json();
    expect(created.name).toBe(name);
  });
});
